# -*- coding: utf-8 -*-
"""South Africa, CAPS FET Grade 12 (NSC): Physical Sciences (Chemistry, Physics) and Life Sciences. UNITS(12)."""
from za_sci import S, GM
from za_fet import U, PC, PP, LS, M, vpm, doppler, DOPPLER, FERT, VERT, HUMAN, PLANT, PLANT2, PLANT3


def UNITS(grade):
    assert grade == 12
    g = 12
    return [
        # ---------------- Physics ----------------
        U(PP, 1, "momentum-and-impulse", "Momentum and impulse",
          "Momentum, p = mv, as a vector; Newton's second law in terms of momentum, F<sub>net</sub> = Δp/Δt; the conservation of linear momentum in an isolated system; elastic and inelastic collisions; impulse, F<sub>net</sub>Δt = Δp, and safety devices.",
          "Momentum and Impulse", "momentum",
          "momentum, conservation of momentum, elastic and inelastic collisions, impulse and safety",
          "p = mv and impulse = Δp", "In an isolated system the total momentum is conserved.",
          "Momentum is the product of mass and velocity, p = mv; it is a vector, so choose a positive direction. Newton's second law can be written as F<sub>net</sub> = Δp/Δt: the resultant force equals the rate of change of momentum.",
          "In an isolated system (no external resultant force) the total momentum before a collision equals the total momentum after it. In an elastic collision kinetic energy is also conserved; in an inelastic collision it is not. Impulse F<sub>net</sub>Δt = Δp: airbags, crumple zones and arrestor beds increase Δt, which reduces the force.",
          [("A 2 kg ball at 3 m·s⁻¹. Momentum?", ["p = mv"], "6 kg·m·s⁻¹"),
           ("A 1 kg trolley at 4 m·s⁻¹ joins a 1 kg trolley at rest. Common velocity?", ["Total p = 4"], "2 m·s⁻¹")],
          ["Forgetting that momentum has a direction.", "Thinking kinetic energy is conserved in every collision.", "Thinking an airbag reduces the change in momentum."],
          [("How does an airbag reduce injury?", "It increases the time over which the momentum changes, so the force on the passenger is smaller."),
           ("When is momentum conserved?", "When no external resultant force acts on the system (an isolated system).")],
          lambda X: S(X, [("Momentum and impulse", "caon_hs12:energy-and-momentum:3"),
                          ("Momentum and impulse problems", "au_sr11p:linear-motion-and-force:4"),
                          ("Collisions", "caon_hs12:energy-and-momentum:4"),
                          ("Momentum problems", "caon_hs12:energy-and-momentum:5"),
                          ("Impulse and safety", "cabc_s11:momentum-and-impulse:5:12")]), g),
        U(PP, 2, "vertical-projectile-motion", "Vertical projectile motion in one dimension",
          "The motion of objects thrown vertically upwards or downwards, or dropped, near the Earth's surface; the acceleration is g = 9.8 m·s⁻² downwards; equations of motion; position–time, velocity–time and acceleration–time graphs for vertical projectile motion, including bouncing.",
          "Vertical Projectile Motion", "vertical projectile motion",
          "objects thrown up and dropped, free fall, equations of motion, and graphs of vertical motion",
          "The acceleration is always 9.8 m·s⁻² downwards.", "At the highest point v = 0, but a = g.",
          "A projectile moves under gravity alone (air resistance is ignored), so it is in free fall with a constant acceleration of 9.8 m·s⁻² downwards, whether it is moving up, at the top, or coming down. Choose up or down as positive and keep the signs consistent.",
          "Use v = u + aΔt, Δy = uΔt + ½aΔt² and v² = u² + 2aΔy. The time to go up equals the time to come down to the same height. On a velocity–time graph the line is straight with a gradient of −9.8 m·s⁻² (up positive); the area gives the displacement.",
          [("A ball is thrown up at 9.8 m·s⁻¹. Time to the top?", ["v = u + at"], "1 s"),
           ("What is the acceleration at the highest point?", ["Gravity still acts."], "9.8 m·s⁻² downwards")],
          ["Thinking the acceleration is zero at the top.", "Mixing up the signs of g and u.", "Thinking a heavier ball falls faster when air resistance is ignored."],
          [("What does the velocity–time graph of a bouncing ball look like?", "Straight sloping lines with the same gradient, with a sudden change of sign of the velocity at each bounce."),
           ("Why does the ball take the same time to go up and come down?", "The acceleration is the same in both directions, so the motion is symmetrical.")],
          lambda X: S(X, [("Free fall", "caon_hs11:kinematics:4"),
                          ("Free fall problems", "in_s11p:motion-in-a-straight-line:3"),
                          ("Thrown upwards", [(X.f(lambda R: vpm(R, "h")), 7), (X.f(lambda R: vpm(R, "t")), 7), (X.f(lambda R: vpm(R, "tt")), 6)]),
                          ("Velocity during the flight", [(X.f(lambda R: vpm(R, "v")), 20)]),
                          ("Dropped objects", [(X.f(lambda R: vpm(R, "drop")), 10), (X.f(lambda R: vpm(R, "hit")), 10)])]), g),
        U(PP, 3, "work-energy-and-power", "Work, energy and power",
          "Work done by a force, W = FΔx cos θ; the work–energy theorem, W<sub>net</sub> = ΔEₖ; conservative and non-conservative forces; the conservation of mechanical energy and its use when non-conservative forces act; power, P = W/Δt = Fv; efficiency.",
          "Work, Energy and Power", "work, energy and power",
          "work done, the work–energy theorem, conservative and non-conservative forces, power and efficiency",
          "W = FΔx cos θ", "W<sub>net</sub> = ΔEₖ",
          "Work is done when a force moves an object: W = FΔx cos θ, where θ is the angle between the force and the displacement. A force perpendicular to the motion does no work. The work–energy theorem: the net work done on an object equals its change in kinetic energy.",
          "Gravity is a conservative force (the work it does does not depend on the path); friction is non-conservative. W<sub>nc</sub> = ΔEₖ + ΔEₚ. Power is the rate of doing work: P = W/Δt, and for constant velocity P<sub>ave</sub> = Fv<sub>ave</sub>.",
          [("A 50 N force pushes a box 4 m along the floor. Work?", ["W = FΔx"], "200 J"),
           ("A 600 W motor runs for 10 s. Work done?", ["W = PΔt"], "6 000 J")],
          ["Forgetting the cos θ when the force is at an angle.", "Thinking friction can be conservative.", "Mixing up power and energy."],
          [("Does the normal force do work on a car driving along a flat road?", "No, because it is perpendicular to the displacement."),
           ("Why does a motor need more power to climb a hill quickly?", "More work must be done against gravity in a shorter time.")],
          lambda X: S(X, [("Work done by a force", "in_s11p:work-energy-and-power:1"),
                          ("Work and energy", "caon_hs12:energy-and-momentum:1"),
                          ("Conservation of energy", "in_s11p:work-energy-and-power:3"),
                          ("Power and efficiency", "in_s11p:work-energy-and-power:4"),
                          ("Power", "caon_hs11:energy-and-society:4")]), g),
        U(PP, 4, "doppler-effect", "Doppler effect",
          "The Doppler effect with sound: the change in observed frequency when a source moves towards or away from a stationary listener, or a listener moves relative to a stationary source; f<sub>L</sub> = (v ± v<sub>L</sub>)/(v ± v<sub>s</sub>) f<sub>s</sub>; applications such as ultrasound and speed traps; the red shift of light from galaxies.",
          "Doppler Effect", "the Doppler effect",
          "the change in pitch of moving sources, the Doppler equation, ultrasound and red shift",
          "Towards: higher frequency. Away: lower frequency.", "The frequency of the source itself does not change.",
          "When a source of sound moves towards a listener, the wavefronts in front of it are squashed together: the wavelength is shorter and the listener hears a higher frequency. When it moves away, the wavefronts are spread out and the frequency heard is lower. The frequency emitted by the source does not change.",
          "Use f<sub>L</sub> = (v ± v<sub>L</sub>)/(v ± v<sub>s</sub>) × f<sub>s</sub>, where v is the speed of sound: choose the signs so that the frequency rises when the source and listener get closer. The Doppler effect is used to measure blood flow and the heartbeat of a foetus. Light from distant galaxies is red-shifted, showing that the universe is expanding.",
          [("A 500 Hz source approaches at 40 m·s⁻¹ (v = 340 m·s⁻¹). f<sub>L</sub>?", ["340/(340 − 40) × 500"], "567 Hz"),
           ("Light from a galaxy is red-shifted. Is it moving towards us?", ["Longer wavelengths"], "no, it is moving away")],
          ["Using + for an approaching source in the denominator.", "Thinking the source's own frequency changes.", "Mixing up loudness and pitch."],
          [("Why does the siren's pitch drop suddenly as an ambulance passes?", "Before it passes it is approaching (higher frequency); after it passes it is moving away (lower frequency)."),
           ("How is the Doppler effect used in medicine?", "Ultrasound reflected from moving blood cells changes frequency, which shows the speed and direction of blood flow.")],
          lambda X: S(X, [("What is the Doppler effect?", [(X.pool(DOPPLER[:12]), 14), ("caon_hs11:waves-and-sound:1", 6)]),
                          ("Approaching sources", [(X.f(lambda R: doppler(R, "app")), 20)]),
                          ("Sources moving away", [(X.f(lambda R: doppler(R, "rec")), 20)]),
                          ("Moving listeners and finding speeds", [(X.f(lambda R: doppler(R, "lis")), 10), (X.f(lambda R: doppler(R, "vs")), 10)]),
                          ("Applications and red shift", [(X.pool(DOPPLER[12:]), 11)] + GM(X, "uk_science_y11_waves_and_the_electromagnetic_spectrum", "g_use", "g_order", n=9))]), g),
        U(PP, 5, "electric-circuits-and-internal-resistance", "Electric circuits: internal resistance",
          "Internal resistance and the emf of a cell, ε = I(R + r); terminal potential difference and 'lost volts'; series–parallel networks of resistors with internal resistance; the effect of changing the external resistance; power in circuits.",
          "Electric Circuits and Internal Resistance", "internal resistance",
          "emf, internal resistance, terminal potential difference, series–parallel networks and power",
          "ε = I(R + r)", "Terminal p.d. = emf − Ir",
          "A real battery has internal resistance r. When a current flows, some potential difference ('lost volts', Ir) is used inside the battery, so the terminal potential difference V = ε − Ir is less than the emf. The emf is the terminal potential difference when no current flows.",
          "Solve series–parallel networks step by step: find the equivalent resistance of each parallel part, add the series resistances and r, then I = ε/(R + r). If the external resistance is decreased, the current increases, the lost volts increase and the terminal potential difference decreases.",
          [("ε = 12 V, r = 1 Ω, R = 5 Ω. Current?", ["I = ε/(R + r)"], "2 A"),
           ("Same circuit. Terminal potential difference?", ["V = IR"], "10 V")],
          ["Forgetting to add r to the external resistance.", "Thinking the terminal p.d. always equals the emf.", "Adding parallel resistors directly."],
          [("Why does a car's headlights dim when the starter motor runs?", "The large current makes the lost volts (Ir) in the battery large, so the terminal p.d. drops."),
           ("How can you find the internal resistance in an experiment?", "Plot terminal p.d. against current: the gradient of the line is −r and the y-intercept is the emf.")],
          lambda X: S(X, [("Circuits with real cells", "au_sr11p:electrical-circuits:5"),
                          ("Cells and internal resistance", "in_s12p:current-electricity:4"),
                          ("E.m.f. and internal resistance", "al_phys:electricity:5:12"),
                          ("Series and parallel resistors", "au_sr11p:electrical-circuits:3"),
                          ("Series and parallel circuits", "al_phys:electricity:3:12")]), g),
        U(PP, 6, "electrodynamics", "Electrodynamics",
          "Electric motors and generators: the motor effect and Fleming's left-hand rule; DC and AC generators and Faraday's law; alternating current: root mean square values, V<sub>rms</sub> = V<sub>max</sub>/√2 and P<sub>ave</sub> = V<sub>rms</sub>I<sub>rms</sub>; uses of AC and DC.",
          "Electrodynamics: Motors, Generators and AC", "motors and generators",
          "electric motors, generators, alternating current, rms values and average power",
          "A motor turns electrical energy into mechanical energy; a generator does the opposite.", "Vrms = Vmax / √2",
          "An electric motor works because a current-carrying coil in a magnetic field experiences a force (the motor effect); a split-ring commutator reverses the current every half turn so the coil keeps turning. A generator uses electromagnetic induction: a coil turning in a magnetic field has a changing flux, which induces an emf.",
          "An AC generator uses slip rings and produces alternating current; a DC generator uses a split-ring commutator. Eskom supplies AC at 230 V (rms) and 50 Hz. The rms value is the DC value that would give the same power: V<sub>rms</sub> = V<sub>max</sub>/√2, I<sub>rms</sub> = I<sub>max</sub>/√2, and P<sub>ave</sub> = V<sub>rms</sub>I<sub>rms</sub>.",
          [("V<sub>max</sub> = 325 V. V<sub>rms</sub>?", ["÷ √2"], "230 V"),
           ("Which part of a DC motor reverses the current?", ["Two half rings"], "the split-ring commutator")],
          ["Mixing up slip rings and split rings.", "Using peak values to find average power.", "Thinking a generator makes energy from nothing."],
          [("Why is electricity transmitted at very high voltage?", "For the same power the current is smaller, so less energy is lost as heat in the cables (P = I²R)."),
           ("Why is AC used for the grid?", "Its voltage can easily be stepped up and down with transformers.")],
          lambda X: S(X, [("Motors, generators and transformers", "au_sr12p:electromagnetism:4"),
                          ("Motors and generators", "cabc_s11:magnetic-forces-and-induction:4:12"),
                          ("Peak and rms values", "in_s12p:alternating-current:1"),
                          ("Transformers and AC problems", "in_s12p:alternating-current:5"),
                          ("Magnetic fields and the motor principle", "caon_hs11:electricity-and-magnetism:4")]), g),
        U(PP, 7, "optical-phenomena-and-properties-of-materials", "Optical phenomena and properties of materials",
          "The photoelectric effect: the threshold frequency and work function, hf = W₀ + Eₖ(max); the photoelectric effect as evidence for the particle nature of light; atomic absorption and emission spectra; line spectra and energy levels.",
          "Photoelectric Effect and Spectra", "the photoelectric effect",
          "photons, the photoelectric effect, work function, threshold frequency, and emission and absorption spectra",
          "E = hf = W₀ + Eₖ(max)", "Below the threshold frequency, no electrons are emitted.",
          "When light of high enough frequency shines on a metal, electrons are emitted (the photoelectric effect). Each photon gives its energy hf to one electron. The work function W₀ is the minimum energy needed to free an electron; the threshold frequency f₀ = W₀/h. Brighter light gives more electrons, but not faster ones.",
          "This could not be explained by the wave model, so it is evidence that light behaves as particles (photons). Atoms absorb or emit photons when electrons move between energy levels: each element has its own line emission spectrum, and dark lines in an absorption spectrum show which wavelengths were absorbed.",
          [("A 4 eV photon hits a metal with W₀ = 2.5 eV. Eₖ(max)?", ["hf − W₀"], "1.5 eV"),
           ("Brighter light of the same frequency: what happens to Eₖ(max)?", ["One photon frees one electron."], "it stays the same; more electrons are emitted")],
          ["Thinking brighter light gives faster electrons.", "Thinking any light can release electrons.", "Forgetting to convert eV to J (1 eV = 1.6 × 10⁻¹⁹ J)."],
          [("Why is the photoelectric effect used in solar panels?", "Light frees electrons in the cell, producing an electric current."),
           ("How do astronomers know what stars are made of?", "They compare the lines in starlight with the line spectra of elements.")],
          lambda X: S(X, [("Photons and the photoelectric effect", "caon_hs12:revolutions-in-modern-physics:1"),
                          ("The photoelectric effect", "au_sr12p:quantum-theory:3"),
                          ("Work function and threshold", "in_s12p:dual-nature-of-radiation-and-matter:3"),
                          ("Stopping potential and energy", "in_s12p:dual-nature-of-radiation-and-matter:2"),
                          ("Energy levels and line spectra", "au_sr12p:quantum-theory:4")]), g),
        # ---------------- Chemistry ----------------
        U(PC, 8, "organic-molecules", "Organic molecules",
          "Organic molecular structures: functional groups, homologous series (alkanes, alkenes, alkynes, haloalkanes, alcohols, aldehydes, ketones, carboxylic acids, esters); IUPAC naming and formulae; structural isomers; physical properties and intermolecular forces; reactions: combustion, esterification, substitution, addition and elimination; plastics and polymers.",
          "Organic Molecules", "organic chemistry",
          "functional groups, IUPAC names, isomers, physical properties, organic reactions and polymers",
          "A homologous series has the same functional group and general formula.", "Alkanes CₙH₂ₙ₊₂; alkenes CₙH₂ₙ.",
          "Organic compounds contain carbon. Each homologous series has a functional group: C=C (alkenes), –OH (alcohols), –CHO (aldehydes), C=O in the chain (ketones), –COOH (carboxylic acids), –COO– (esters). IUPAC names use the longest chain (meth-, eth-, prop-, but-, pent-) and the suffix of the functional group.",
          "Boiling points increase with chain length (stronger London forces) and are higher for alcohols and acids (hydrogen bonds). Alkanes undergo substitution with halogens; alkenes undergo addition (hydrogenation, hydration, halogenation); elimination makes alkenes. An alcohol and a carboxylic acid form an ester. Addition polymers such as polythene are made from alkenes.",
          [("Name CH₃CH₂CH₂OH.", ["3 carbons, –OH on C1"], "propan-1-ol"),
           ("Ethanol + ethanoic acid → ?", ["Esterification"], "ethyl ethanoate + water")],
          ["Numbering the chain from the wrong end.", "Thinking alkenes undergo substitution.", "Mixing up aldehydes and ketones."],
          [("Why does butane boil at a higher temperature than propane?", "It is a longer molecule with stronger London forces."),
           ("Why are plastics a problem for the environment?", "Most are not biodegradable, so they last for hundreds of years in landfills and oceans.")],
          lambda X: S(X, [("Naming hydrocarbons", "caon_hs12:organic-chemistry:1"),
                          ("Functional groups", "caon_hs12:organic-chemistry:2"),
                          ("Alcohols, aldehydes and ketones", "caon_hs12:organic-chemistry:3"),
                          ("Acids, esters and amines", M("caon_hs12:organic-chemistry:4", "au_sr12c:organic-chemistry:4")),
                          ("Isomers, reactions and polymers", "caon_hs12:organic-chemistry:5")]), g, allow=("london",)),
        U(PC, 9, "rate-and-extent-of-reaction", "Rate and extent of reaction",
          "Reaction rate as the change in concentration (or mass, or volume) per unit time; factors that affect the rate: nature of reactants, concentration (pressure), surface area, temperature and catalysts; collision theory; the Maxwell–Boltzmann distribution; measuring rates of reaction.",
          "Rate of Reaction", "reaction rate",
          "reaction rate, factors that affect rate, collision theory, activation energy, catalysts and measuring rates",
          "Rate = change in amount ÷ time.", "Only collisions with enough energy and the right orientation are effective.",
          "Collision theory: particles must collide with enough energy (at least the activation energy) and with the correct orientation for a reaction to happen. The rate increases if collisions happen more often or more of them are effective.",
          "Higher concentration or pressure and larger surface area give more collisions per second. A higher temperature gives particles more kinetic energy, so more of them have enough energy to react (seen on a Maxwell–Boltzmann curve). A catalyst gives a pathway with a lower activation energy. Rates are measured by gas volume, mass loss or colour change.",
          [("50 cm³ of gas forms in 25 s. Average rate?", ["volume ÷ time"], "2 cm³·s⁻¹"),
           ("Why does powdered zinc react faster than a lump?", ["Surface area"], "it has a larger surface area, so there are more collisions")],
          ["Thinking a catalyst increases the energy of the particles.", "Thinking a higher temperature only increases the number of collisions.", "Thinking a catalyst changes the yield."],
          [("Why is food kept in a fridge?", "The low temperature slows down the reactions that make food go off."),
           ("What does the Maxwell–Boltzmann curve show?", "How many particles have each kinetic energy; at a higher temperature more particles have energy above the activation energy.")],
          lambda X: S(X, [("Collision theory", "au_sr11c:rates-of-reaction:1"),
                          ("Factors that affect rate", "au_sr11c:rates-of-reaction:2"),
                          ("Measuring rates of reaction", "au_sr11c:rates-of-reaction:3"),
                          ("Collision theory and catalysts", "caon_hs12:energy-changes-and-rates-of-reaction:4"),
                          ("Rate data and investigations", "au_sr11c:rates-of-reaction:5")]), g),
        U(PC, 10, "chemical-equilibrium", "Chemical equilibrium",
          "Open and closed systems; reversible reactions and dynamic equilibrium; the equilibrium constant K<sub>c</sub> and its expression; calculations with K<sub>c</sub> (using a table of moles); Le Chatelier's principle and the effect of concentration, pressure and temperature; the effect of a catalyst; industrial applications such as the Haber process.",
          "Chemical Equilibrium", "chemical equilibrium",
          "dynamic equilibrium, Kc expressions and calculations, Le Chatelier's principle and industrial processes",
          "At equilibrium the forward and reverse rates are equal.", "Only temperature changes the value of Kc.",
          "In a closed system a reversible reaction reaches dynamic equilibrium: the forward and reverse reactions continue at the same rate, so the concentrations stay constant. For aA + bB ⇌ cC + dD, K<sub>c</sub> = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ; solids and pure liquids are left out. A large K<sub>c</sub> means mostly products.",
          "Le Chatelier's principle: when an equilibrium is disturbed, it shifts to oppose the change. Adding a reactant shifts it to the right; increasing pressure favours the side with fewer moles of gas; increasing temperature favours the endothermic reaction. A catalyst speeds up both reactions equally and does not shift the equilibrium.",
          [("N₂ + 3H₂ ⇌ 2NH₃ (exothermic). Temperature is raised. Effect on the yield of NH₃?", ["Endothermic direction is favoured."], "it decreases"),
           ("Write K<sub>c</sub> for H₂ + I₂ ⇌ 2HI.", ["Products over reactants"], "[HI]² / ([H₂][I₂])")],
          ["Thinking reactions stop at equilibrium.", "Including solids in K<sub>c</sub>.", "Thinking a catalyst increases the yield."],
          [("Why is the Haber process done at about 450 °C even though a lower temperature gives more ammonia?", "At low temperatures the rate is too slow; 450 °C is a compromise between rate and yield."),
           ("What changes the value of K<sub>c</sub>?", "Only a change in temperature.")],
          lambda X: S(X, [("Dynamic equilibrium", "au_sr12c:chemical-equilibrium:1"),
                          ("Le Chatelier's principle", "au_sr12c:chemical-equilibrium:2"),
                          ("Equilibrium expressions", "au_sr12c:chemical-equilibrium:3"),
                          ("Calculating K<sub>c</sub>", M("au_sr12c:chemical-equilibrium:4", "caon_hs12:chemical-systems-and-equilibrium:3")),
                          ("Equilibrium amounts and industrial processes", "au_sr12c:chemical-equilibrium:5")]), g),
        U(PC, 11, "acids-bases-and-titrations", "Acids and bases",
          "Strong and weak acids and bases; concentrated and dilute solutions; the ionisation constant of water, K<sub>w</sub> = [H₃O⁺][OH⁻] = 1 × 10⁻¹⁴ at 25 °C; pH = −log[H₃O⁺]; hydrolysis of salts; acid–base titrations, the choice of indicator and the equivalence point; K<sub>a</sub> and K<sub>b</sub>.",
          "Acids and Bases: pH and Titrations", "pH and titrations",
          "strong and weak acids, Kw, pH calculations, salt hydrolysis, titrations and indicators",
          "pH = −log[H₃O⁺]", "Kw = [H₃O⁺][OH⁻] = 1 × 10⁻¹⁴ at 25 °C",
          "A strong acid (HCl, HNO₃, H₂SO₄) ionises completely in water; a weak acid (ethanoic acid) ionises only partly, so K<sub>a</sub> is small. 'Strong' is about ionisation; 'concentrated' is about how much acid is dissolved. pH = −log[H₃O⁺]; in water at 25 °C, [H₃O⁺][OH⁻] = 1 × 10⁻¹⁴.",
          "In a titration, a standard solution is added from a burette until the equivalence point; then n(acid)/n(base) equals the mole ratio. Salts of a strong acid and a weak base are acidic (choose methyl orange); salts of a weak acid and a strong base are basic (choose phenolphthalein).",
          [("[H₃O⁺] = 1 × 10⁻³ mol·dm⁻³. pH?", ["−log"], "3"),
           ("Which indicator for ethanoic acid and NaOH?", ["The salt solution is basic."], "phenolphthalein")],
          ["Mixing up strong and concentrated.", "Thinking pH 7 is the end point of every titration.", "Forgetting the mole ratio for H₂SO₄."],
          [("Why is a solution of sodium ethanoate basic?", "The ethanoate ion reacts with water (hydrolysis) to form OH⁻ ions."),
           ("What is the difference between the equivalence point and the end point?", "The equivalence point is when exactly the right amounts have reacted; the end point is when the indicator changes colour.")],
          lambda X: S(X, [("pH of strong acids and bases", "au_sr12c:acids-bases-and-ph:2"),
                          ("Weak acids and K<sub>a</sub>", "au_sr12c:acids-bases-and-ph:3"),
                          ("pH, pOH and K<sub>a</sub>", "caon_hs12:chemical-systems-and-equilibrium:4"),
                          ("Strong acids and bases", "al_chem:acids-bases-and-electrode-potentials:1:13"),
                          ("Titrations", "au_sr12c:acids-bases-and-ph:5")]), g),
        U(PC, 12, "electrochemical-reactions", "Electrochemical reactions",
          "Galvanic (voltaic) cells and electrolytic cells; the anode (oxidation) and cathode (reduction); the salt bridge; cell notation; standard electrode potentials and E°<sub>cell</sub> = E°<sub>cathode</sub> − E°<sub>anode</sub>; electrolysis of copper(II) chloride, the refining of copper, the chlor-alkali industry and the extraction of aluminium.",
          "Electrochemical Reactions", "electrochemistry",
          "galvanic cells, electrolytic cells, the salt bridge, cell potentials, electrolysis and electrochemical industries",
          "Oxidation happens at the anode; reduction at the cathode.", "E°cell = E°cathode − E°anode",
          "A galvanic cell changes chemical energy into electrical energy by a spontaneous redox reaction; an electrolytic cell uses electrical energy to cause a non-spontaneous reaction. In both, oxidation happens at the anode and reduction at the cathode. The salt bridge keeps the solutions neutral by letting ions move.",
          "From the table of standard reduction potentials, the half-cell with the higher E° is reduced (cathode). A positive E°<sub>cell</sub> means the reaction is spontaneous. Electrolysis is used to refine copper, to make chlorine and sodium hydroxide from brine (chlor-alkali), and to extract aluminium from bauxite.",
          [("Zn²⁺/Zn −0.76 V; Cu²⁺/Cu +0.34 V. E°<sub>cell</sub>?", ["Cu is the cathode."], "+1.10 V"),
           ("In a galvanic cell, which electrode is negative?", ["Electrons leave it."], "the anode")],
          ["Thinking the anode is always positive.", "Subtracting E° values the wrong way round.", "Thinking electrons flow through the salt bridge."],
          [("Why is aluminium extraction expensive?", "It needs a huge amount of electrical energy, and the carbon anodes burn away and must be replaced."),
           ("What is the cell notation for the Zn–Cu cell?", "Zn | Zn²⁺ || Cu²⁺ | Cu")],
          lambda X: S(X, [("Galvanic cells", "au_sr12c:electrochemical-cells:1"),
                          ("Standard electrode potentials", "au_sr12c:electrochemical-cells:2"),
                          ("Electrolytic cells", "au_sr12c:electrochemical-cells:3"),
                          ("Electrolysis", "caon_hs12:electrochemistry:4"),
                          ("Batteries and corrosion", "caon_hs12:electrochemistry:5")]), g),
        U(PC, 13, "the-chemical-industry-fertilisers", "The chemical industry: fertilisers",
          "The value of fertilisers: the nutrients N, P and K; the fertiliser industry: the Haber process (ammonia), the Ostwald process (nitric acid) and the contact process (sulfuric acid); making ammonium nitrate, ammonium sulfate and phosphate fertilisers; NPK ratios; the environmental impact of fertilisers, including eutrophication.",
          "The Chemical Industry: Fertilisers", "fertilisers",
          "N, P and K, the Haber, Ostwald and contact processes, ammonium salts, NPK ratios and eutrophication",
          "Plants need nitrogen, phosphorus and potassium.", "Ammonia is made by the Haber process.",
          "Plants need nitrogen for proteins and leaf growth, phosphorus for roots, flowers and ATP, and potassium for fruit and disease resistance. Harvesting removes these nutrients, so farmers add fertilisers. A label 3:2:1 (25) gives the ratio of N : P : K and the total percentage of nutrients.",
          "Ammonia is made by the Haber process (N₂ + 3H₂ ⇌ 2NH₃, iron catalyst); nitric acid by the Ostwald process; sulfuric acid by the contact process (V₂O₅ catalyst). Ammonia and these acids make ammonium nitrate and ammonium sulfate. Too much fertiliser runs off into rivers and dams and causes eutrophication.",
          [("A 2 kg bag is 3:2:1 (30). Mass of nitrogen?", ["Nutrients = 30% of 2 kg = 600 g; N is 3/6"], "300 g"),
           ("Which process makes sulfuric acid?", ["V₂O₅ catalyst"], "the contact process")],
          ["Mixing up the Haber and Ostwald processes.", "Reading the NPK ratio as masses in kilograms.", "Thinking more fertiliser always gives a bigger harvest."],
          [("Why is eutrophication harmful?", "Algae grow quickly and then die; bacteria decomposing them use up the oxygen, so fish die."),
           ("Why are fertilisers important in South Africa?", "They increase crop yields and help feed a growing population.")],
          lambda X: S(X, [("Nutrients and fertilisers", [(X.pool(FERT[:5] + FERT[20:21] + FERT[24:26] + FERT[27:28]), 9), ("au_sr11e:biogeochemical-cycles:3", 11)]),
                          ("The Haber process", [(X.pool(FERT[5:6] + FERT[8:9] + FERT[11:13] + FERT[21:24] + FERT[26:27]), 9), ("au_sr12c:chemical-equilibrium:5", 11)]),
                          ("Nitric acid, sulfuric acid and fertiliser salts", [(X.pool(FERT[6:8] + FERT[9:11] + FERT[13:17] + FERT[28:]), 12), ("au_sr12c:chemical-equilibrium:2", 8)]),
                          ("Fertilisers and the environment", [(X.pool(FERT[17:20]), 3), ("au_sr11e:biogeochemical-cycles:4", 17)]),
                          ("Industrial equilibrium", M("au_sr12c:chemical-equilibrium:5", "caon_hs12:chemical-systems-and-equilibrium:1"))]), g),
        # ---------------- Life Sciences ----------------
        U(LS, 14, "dna-the-code-of-life", "DNA: the code of life",
          "The structure of DNA and RNA; the location of DNA (nucleus, mitochondria, chloroplasts); DNA replication; protein synthesis: transcription and translation; the genetic code; DNA profiling and its uses.",
          "DNA: The Code of Life", "DNA and protein synthesis",
          "DNA and RNA, base pairing, replication, transcription, translation and DNA profiling",
          "A pairs with T (in RNA, U); C pairs with G.", "DNA → mRNA → protein.",
          "DNA is a double helix of two strands of nucleotides (a sugar, a phosphate and a base). The bases pair: adenine with thymine and cytosine with guanine, joined by hydrogen bonds. In replication the helix unwinds, and each strand is a template for a new strand (semi-conservative replication).",
          "In transcription, a gene's DNA is copied into mRNA in the nucleus (U replaces T). In translation, ribosomes read the mRNA in codons of three bases; tRNA brings the matching amino acids, which are joined into a protein. DNA profiling compares DNA fragments to identify people, for paternity tests and in forensics.",
          [("DNA strand ATG CCA. Complementary DNA?", ["A–T, C–G"], "TAC GGT"),
           ("DNA template TAC. mRNA codon?", ["U instead of T"], "AUG")],
          ["Pairing A with U in DNA.", "Thinking proteins are made in the nucleus.", "Mixing up codons (mRNA) and anticodons (tRNA)."],
          [("Why is DNA replication called semi-conservative?", "Each new DNA molecule has one old strand and one new strand."),
           ("Is DNA profiling proof of guilt?", "It is strong evidence, but samples can be contaminated, so it is used with other evidence.")],
          lambda X: S(X, [("DNA structure", "caon_hs12:molecular-genetics:1"),
                          ("DNA replication", "caon_hs12:molecular-genetics:2"),
                          ("Transcription", "au_sr12b:dna-genes-and-protein-synthesis:3"),
                          ("Translation and the genetic code", "au_sr12b:dna-genes-and-protein-synthesis:4"),
                          ("Gel electrophoresis and DNA profiling", "au_sr12b:mutations-and-biotechnology:4")]), g),
        U(LS, 15, "meiosis", "Meiosis",
          "The process of meiosis: meiosis I and meiosis II; crossing over and the random arrangement of chromosomes as sources of variation; the importance of meiosis; abnormal meiosis (non-disjunction) and Down syndrome; differences between mitosis and meiosis.",
          "Meiosis", "meiosis",
          "meiosis I and II, crossing over, random assortment, non-disjunction and comparing mitosis and meiosis",
          "Meiosis makes four haploid gametes.", "Crossing over and random arrangement cause variation.",
          "Meiosis halves the chromosome number: a diploid cell (2n = 46 in humans) gives four haploid gametes (n = 23) that are genetically different. In prophase I homologous chromosomes pair and exchange segments (crossing over); in metaphase I the pairs line up at random.",
          "Meiosis keeps the chromosome number constant from one generation to the next and produces variation. Non-disjunction is when chromosomes fail to separate; a gamete with an extra chromosome 21 can lead to Down syndrome (trisomy 21).",
          [("A cell with 2n = 8 undergoes meiosis. Chromosomes in each gamete?", ["Halved"], "4"),
           ("When does crossing over happen?", ["Homologous pairs"], "prophase I")],
          ["Thinking meiosis makes identical cells.", "Thinking meiosis happens in all body cells.", "Mixing up chromatids and homologous chromosomes."],
          [("Why is meiosis needed for sexual reproduction?", "When two gametes fuse, the zygote gets the full diploid number again."),
           ("What is the main difference between mitosis and meiosis?", "Mitosis gives two identical diploid cells; meiosis gives four different haploid cells.")],
          lambda X: S(X, [("Meiosis", "caon_hs11:genetic-processes:1"),
                          ("Meiosis and variation", "au_sr12b:cell-division-and-inheritance:1"),
                          ("Meiosis in detail", "in_s11b:cell-cycle-and-cell-division:3"),
                          ("Chromosome numbers", "in_s11b:cell-cycle-and-cell-division:4"),
                          ("Mitosis and meiosis", "cabc_s11:reproduction-and-life-cycles:3:11")]), g),
        U(LS, 16, "reproduction-in-vertebrates", "Reproduction in vertebrates",
          "Reproductive strategies in vertebrates: external and internal fertilisation; ovipary, ovovivipary and vivipary; the amniotic egg; precocial and altricial development; parental care.",
          "Reproduction in Vertebrates", "reproductive strategies",
          "external and internal fertilisation, ovipary, ovovivipary, vivipary, amniotic eggs and parental care",
          "Internal fertilisation is an adaptation to life on land.", "More parental care, fewer young.",
          "Fertilisation is external in most fish and amphibians (in water) and internal in reptiles, birds and mammals. Oviparous animals lay eggs that develop outside the body; ovoviviparous animals keep the eggs inside until they hatch; viviparous animals (most mammals) feed the embryo through a placenta and give birth to live young.",
          "Reptiles and birds lay amniotic eggs with a shell, amnion, yolk sac, allantois and chorion that protect the embryo on land. Precocial young (antelope calves, chicks) can move soon after birth; altricial young (kittens, many songbirds) are helpless and need care. Animals that give more parental care produce fewer young.",
          [("Which type of development does a springbok calf show?", ["It runs within hours."], "precocial"),
           ("Which membrane in an egg stores waste?", ["Not the amnion"], "the allantois")],
          ["Thinking all reptiles lay eggs (some are ovoviviparous).", "Mixing up ovipary and vivipary.", "Thinking fish give a lot of parental care."],
          [("Why do frogs lay so many eggs?", "Fertilisation is external and there is little care, so most eggs and tadpoles are lost."),
           ("What is the advantage of the amniotic egg?", "The embryo develops in fluid, protected from drying out, so reptiles and birds could breed on land.")],
          lambda X: S(X, [("Fertilisation", [(X.pool(VERT[:5]), 5)] + GM(X, "uk_science_y5_reproduction_in_plants_and_animals", "g_part", "g_step", n=4) + [("in_s12b:human-reproduction:4", 11)]),
                          ("Ovipary, ovovivipary and vivipary", [(X.pool(VERT[5:11] + VERT[24:25]), 7)] + GM(X, "uk_science_y5_life_cycles", "g_stage", "g_group", "g_feat", n=13)),
                          ("The amniotic egg", [(X.pool(VERT[11:17] + VERT[25:]), 7)] + GM(X, "sg_science_p3_life_cycles_of_animals", "g_order", "g_has", "B1", n=13)),
                          ("Parental care", [(X.pool(VERT[17:24]), 7), ("in_s12b:organisms-and-populations:3", 13)]),
                          ("Reproduction and life cycles", "cabc_s11:reproduction-and-life-cycles:5:11")]), g),
        U(LS, 17, "human-reproduction", "Human reproduction",
          "The structure of the male and female reproductive systems; puberty and the role of hormones; gametogenesis (spermatogenesis and oogenesis); the menstrual cycle and its hormonal control (FSH, LH, oestrogen and progesterone); fertilisation, implantation and the development of the zygote; the placenta and the role of the amnion and umbilical cord.",
          "Human Reproduction", "human reproduction",
          "the reproductive systems, puberty, gametogenesis, the menstrual cycle, fertilisation, implantation and the placenta",
          "FSH and LH from the pituitary control the menstrual cycle.", "Fertilisation happens in the Fallopian tube.",
          "Sperm are made in the testes by meiosis (spermatogenesis) under the control of testosterone. Eggs develop in follicles in the ovaries (oogenesis). Puberty starts when the pituitary gland releases FSH and LH.",
          "In the menstrual cycle, FSH makes a follicle grow, which releases oestrogen; a surge of LH causes ovulation on about day 14; the corpus luteum releases progesterone, which keeps the uterus lining thick. If the egg is fertilised in the Fallopian tube, the zygote divides and implants in the endometrium; the placenta passes food and oxygen to the foetus through the umbilical cord.",
          [("Which hormone causes ovulation?", ["A surge mid-cycle"], "LH"),
           ("Where is the zygote implanted?", ["The thick lining"], "in the endometrium of the uterus")],
          ["Thinking ovulation and menstruation are the same.", "Thinking the mother's blood flows into the foetus.", "Mixing up FSH and LH."],
          [("Why does the uterus lining break down if no pregnancy happens?", "The corpus luteum degenerates, so the progesterone level falls."),
           ("What does the amnion do?", "It holds amniotic fluid that protects the foetus from shocks and drying out.")],
          lambda X: S(X, [("Reproductive systems", M("in_s12b:human-reproduction:1", GM(X, "uk_science_y7_human_reproduction", "g_part", "g_voc"), GM(X, "sg_science_s2_human_sexual_reproductive_system", "g_part", "g_pub"))),
                          ("Gametogenesis", "in_s12b:human-reproduction:2"),
                          ("The menstrual cycle", "in_s12b:human-reproduction:3"),
                          ("Fertilisation and implantation", M("in_s12b:human-reproduction:4", GM(X, "uk_science_y7_human_reproduction", "g_step", "g_plac"))),
                          ("Pregnancy and birth", M("in_s12b:human-reproduction:5", GM(X, "uk_science_y7_human_reproduction", "g_gest", "B1"), GM(X, "sg_science_p5_reproduction_in_humans", "g_gest", "g_step")))]), g),
        U(LS, 18, "genetics-and-inheritance", "Genetics and inheritance",
          "Genes, alleles, genotype and phenotype; monohybrid crosses with complete dominance, incomplete dominance and co-dominance; sex determination; sex-linked inheritance (haemophilia, colour blindness); blood groups; dihybrid crosses; pedigree diagrams; mutations; genetic engineering, cloning and paternity testing.",
          "Genetics and Inheritance", "genetics",
          "alleles, genotypes, monohybrid and dihybrid crosses, incomplete and co-dominance, sex linkage, blood groups and pedigrees",
          "A dominant allele shows in the phenotype if present.", "Tt × Tt gives a 3 : 1 phenotype ratio.",
          "A gene has different forms called alleles. The genotype is the pair of alleles (TT, Tt, tt); the phenotype is the characteristic that shows. In complete dominance Tt looks like TT. In incomplete dominance the heterozygote is intermediate (red × white → pink); in co-dominance both alleles show (blood group AB).",
          "Sex is determined by the X and Y chromosomes: XX female, XY male. Sex-linked alleles such as haemophilia are carried on the X chromosome, so they are more common in males. A dihybrid cross of two heterozygotes (TtRr × TtRr) gives a 9 : 3 : 3 : 1 phenotype ratio.",
          [("Tt × tt. Proportion of tall offspring?", ["Punnett square"], "50%"),
           ("A man with haemophilia (XʰY) has a son with a normal woman (XᴴXᴴ). Chance the son has haemophilia?", ["Sons get the father's Y."], "0%")],
          ["Thinking dominant means more common.", "Thinking a son can inherit an X-linked allele from his father.", "Mixing up genotype and phenotype."],
          [("Why are more males colour-blind than females?", "Males have only one X chromosome, so one recessive allele is enough."),
           ("How can blood groups show that a man is not a child's father?", "If the child has an allele that neither the mother nor the man could have passed on.")],
          lambda X: S(X, [("Monohybrid crosses", "au_sr12b:cell-division-and-inheritance:2"),
                          ("Dihybrid crosses and linkage", "au_sr12b:cell-division-and-inheritance:3"),
                          ("Sex linkage and pedigrees", "au_sr12b:cell-division-and-inheritance:4"),
                          ("Dihybrid crosses and other patterns", "caon_hs11:genetic-processes:3"),
                          ("Sex-linked traits and disorders", "caon_hs11:genetic-processes:4")]), g),
        U(LS, 19, "nervous-system-and-senses", "Responding to the environment: humans",
          "The human nervous system: the central and peripheral nervous systems; the structure and function of neurons; synapses; the reflex arc; the structure and functions of the brain; the human eye (accommodation, pupillary reflex, binocular vision) and ear (hearing and balance); disorders of the eye and ear.",
          "The Nervous System and Senses", "the nervous system",
          "neurons, synapses, the reflex arc, the brain, the eye and the ear",
          "A reflex is a fast, automatic response.", "Receptor → sensory neuron → interneuron → motor neuron → effector.",
          "The central nervous system is the brain and spinal cord; the peripheral nervous system is the nerves. Neurons carry impulses: sensory neurons from receptors, motor neurons to effectors (muscles and glands). Impulses cross synapses using chemical neurotransmitters. A reflex arc gives a quick response without thinking.",
          "The cerebrum controls thought and voluntary actions, the cerebellum controls balance and coordination, and the medulla oblongata controls breathing and heart rate. In the eye, the lens changes shape to focus (accommodation) and the iris controls the size of the pupil. In the ear, the cochlea detects sound and the semicircular canals detect movement for balance.",
          [("Which part of the brain controls balance?", ["Little brain"], "the cerebellum"),
           ("In bright light, what does the pupil do?", ["Protect the retina"], "it becomes smaller")],
          ["Thinking reflexes are controlled by the cerebrum.", "Mixing up sensory and motor neurons.", "Thinking the lens moves forward and backward to focus."],
          [("What is short-sightedness?", "The eyeball is too long or the lens too strong, so distant objects focus in front of the retina; a concave lens corrects it."),
           ("Why is a reflex useful?", "It protects the body from harm quickly, for example pulling your hand away from a hot pot.")],
          lambda X: S(X, [("Neurons and impulses", "in_s11b:neural-control-and-coordination:1"),
                          ("Synapses and reflexes", "in_s11b:neural-control-and-coordination:2"),
                          ("The brain and the nervous system", M("in_s11b:neural-control-and-coordination:3", GM(X, "sg_science_s4_homeostasis_coordination_and_response", "g_nvh", "g_act"))),
                          ("The eye and the ear", M("in_s11b:neural-control-and-coordination:4", GM(X, "sg_science_s4_homeostasis_coordination_and_response", "g_acc", "POOL1"), GM(X, "uk_science_y6_how_we_see", "g_eye", "g_pupil"))),
                          ("Nerve impulses and synapses", "caon_hs12:homeostasis:4")]), g),
        U(LS, 20, "endocrine-system-and-homeostasis", "Human endocrine system and homeostasis",
          "Endocrine glands and their hormones (hypothalamus, pituitary, thyroid, pancreas, adrenal glands, ovaries and testes); negative feedback; homeostatic control of blood glucose (insulin and glucagon), water balance (ADH), salt, carbon dioxide and body temperature; diabetes.",
          "Endocrine System and Homeostasis", "hormones and homeostasis",
          "endocrine glands, hormones, negative feedback, blood glucose, water balance, temperature control and diabetes",
          "Homeostasis keeps the internal environment constant.", "Negative feedback reverses a change.",
          "Hormones are chemical messengers made by endocrine glands and carried in the blood. The pituitary gland controls other glands; the thyroid makes thyroxin (metabolism); the adrenal glands make adrenalin (fight or flight); the pancreas makes insulin and glucagon.",
          "Homeostasis uses negative feedback: when blood glucose rises, insulin makes the liver change glucose to glycogen; when it falls, glucagon makes the liver change glycogen to glucose. ADH controls water balance. When you are too hot, you sweat and blood vessels in the skin dilate (vasodilation); when you are too cold, you shiver and they constrict.",
          [("Blood glucose is high after a meal. Which hormone is released?", ["From the pancreas"], "insulin"),
           ("Which hormone prepares the body for fight or flight?", ["Adrenal glands"], "adrenalin")],
          ["Thinking insulin is an enzyme.", "Mixing up glucagon and glycogen.", "Thinking hormones act as fast as nerves."],
          [("What is type 1 diabetes?", "The pancreas makes little or no insulin, so the blood glucose level is too high; it is treated with insulin injections."),
           ("Why do your hands look pale on a cold day?", "Blood vessels in the skin constrict (vasoconstriction) to reduce heat loss.")],
          lambda X: S(X, [("Endocrine glands", "in_s11b:chemical-coordination-and-integration:1"),
                          ("Hormones and their roles", "in_s11b:chemical-coordination-and-integration:2"),
                          ("Feedback and homeostasis", "au_sr12b:homeostasis:1"),
                          ("Thermoregulation", "au_sr12b:homeostasis:2"),
                          ("Blood glucose", "au_sr12b:homeostasis:4")]), g),
        U(LS, 21, "plant-responses-to-the-environment", "Responding to the environment: plants",
          "Plant hormones: auxins, gibberellins and abscisic acid and their functions; phototropism and geotropism; apical dominance; uses of plant hormones in agriculture; plant defence mechanisms: physical and chemical defences.",
          "Plant Responses to the Environment", "plant responses",
          "auxins, gibberellins, abscisic acid, phototropism, geotropism, apical dominance and plant defences",
          "Auxin moves to the shaded side of a shoot.", "Shoots grow towards light; roots grow towards gravity.",
          "Plants respond to stimuli by growth movements called tropisms. Phototropism: auxin collects on the shaded side of a shoot, where cells grow longer, so the shoot bends towards the light. Geotropism: roots grow downwards (positive) and shoots upwards (negative). The shoot tip makes auxin that inhibits side buds (apical dominance).",
          "Gibberellins stimulate germination, stem elongation and fruit growth; abscisic acid closes stomata and keeps seeds dormant. Auxins are used as rooting powders and weedkillers. Plants defend themselves physically (thorns, hairs, thick bark) and chemically (bitter tannins and poisons).",
          [("A seedling is lit from the left. Which way does it bend?", ["Towards light"], "to the left"),
           ("Which hormone closes stomata in a drought?", ["Stress hormone"], "abscisic acid")],
          ["Thinking auxin collects on the lit side.", "Thinking roots grow away from gravity.", "Thinking plants cannot defend themselves."],
          [("Why does pruning the tip make a plant bushier?", "It removes apical dominance, so the side buds grow into branches."),
           ("How do acacias defend themselves against browsers?", "With thorns and by making more bitter tannins in their leaves.")],
          lambda X: S(X, [("Tropisms", [(X.pool(PLANT[:8] + PLANT[19:24]), 13), (X.pool(PLANT2[:7]), 7)]),
                          ("Plant hormones", [("in_s11b:plant-growth-and-development:2", 12), (X.pool(PLANT2[7:15]), 8)]),
                          ("Uses of plant hormones", [(X.pool(PLANT[8:15]), 7), ("in_s11b:plant-growth-and-development:3", 5), ("caon_hs11:plants-anatomy-growth-and-function:5", 8)]),
                          ("Investigating tropisms", [(X.pool(PLANT2[20:] + PLANT3[:8]), 11), ("in_s11b:plant-growth-and-development:4", 3), ("in_s11b:plant-growth-and-development:5", 2), ("au_sr11b:enzymes-photosynthesis-and-respiration:5", 4)]),
                          ("Plant defences", [(X.pool(PLANT[15:19] + PLANT2[15:20] + PLANT3[8:]), 12), ("caon_hs11:plants-anatomy-growth-and-function:5", 5), ("in_s11b:plant-growth-and-development:2", 3)])]), g),
        U(LS, 22, "evolution", "Evolution by natural selection",
          "Evidence for evolution (fossils, biogeography, comparative anatomy, genetics); variation; theories of evolution (Lamarck, Darwin, punctuated equilibrium); natural selection; artificial selection; speciation through geographic isolation; reproductive isolating mechanisms; evolution in present times (resistance to antibiotics and pesticides).",
          "Evolution by Natural Selection", "evolution",
          "evidence for evolution, Lamarck and Darwin, natural selection, artificial selection, speciation and resistance",
          "Individuals with useful variations survive and reproduce more.", "A species is a group that can interbreed to produce fertile offspring.",
          "Evidence for evolution comes from fossils, the distribution of species (biogeography), homologous structures (such as the pentadactyl limb) and similarities in DNA. Lamarck's theory (use and disuse, inheritance of acquired characteristics) was rejected. Darwin's theory of natural selection: there is variation; more young are born than can survive; those best suited to the environment survive and pass on their alleles.",
          "Punctuated equilibrium proposes long periods of little change interrupted by quick change. New species form when a population is split by a geographic barrier and the groups change until they can no longer interbreed. Bacteria resistant to antibiotics (such as TB bacteria) and insects resistant to pesticides are evolution happening today.",
          [("Why did Lamarck's idea not hold?", ["Can a giraffe pass on a stretched neck?"], "acquired characteristics are not inherited"),
           ("Antibiotic resistance spreads. Which process?", ["Survivors reproduce."], "natural selection")],
          ["Thinking individuals evolve during their lives.", "Thinking organisms change because they need to.", "Thinking evolution means humans came from chimpanzees."],
          [("Why must you finish a course of antibiotics?", "Otherwise the most resistant bacteria may survive and multiply."),
           ("What is a reproductive isolating mechanism?", "Anything that stops two species from interbreeding, such as different breeding seasons or courtship behaviour.")],
          lambda X: S(X, [("Evidence for evolution", "caon_hs11:evolution:1"),
                          ("Natural selection", "caon_hs11:evolution:2"),
                          ("Mechanisms of evolutionary change", "cabc_s11:evolution:3:11"),
                          ("Speciation", "au_sr12b:evolution-and-population-genetics:4"),
                          ("Artificial selection and resistance", "caon_hs11:evolution:4")]), g),
        U(LS, 23, "human-evolution", "Human evolution",
          "Similarities and differences between humans and African apes (bipedalism, the foramen magnum, the pelvis, the spine, brain size, teeth and jaws); the fossil evidence for human evolution in South Africa (Taung Child, Mrs Ples, Little Foot, <i>Australopithecus sediba</i>, <i>Homo naledi</i>); the Out of Africa hypothesis; genetic evidence from mitochondrial DNA.",
          "Human Evolution", "human evolution",
          "humans and African apes, bipedalism, South African hominid fossils, Out of Africa and mitochondrial DNA",
          "Bipedalism is a key feature of hominids.", "Modern humans first evolved in Africa.",
          "Humans share many features with other primates: forward-facing eyes, opposable thumbs and nails instead of claws. Humans differ from African apes in being bipedal: the foramen magnum is under the skull, the spine is S-shaped and the pelvis is short and wide. Humans have a larger brain, a flatter face, smaller jaws and smaller canine teeth.",
          "South Africa's Cradle of Humankind has many hominid fossils: Mrs Ples and Little Foot at Sterkfontein, <i>Australopithecus sediba</i> at Malapa and <i>Homo naledi</i> in the Rising Star Cave; the Taung Child comes from the North West. The Out of Africa hypothesis says that <i>Homo sapiens</i> evolved in Africa and spread across the world; mitochondrial DNA, inherited from the mother, supports it.",
          [("Where is the foramen magnum in a bipedal hominid?", ["The spine enters from below."], "under the skull, towards the front"),
           ("Which species is the Taung Child?", ["Described by Raymond Dart"], "<i>Australopithecus africanus</i>")],
          ["Thinking humans evolved from modern chimpanzees.", "Thinking a bigger brain came before bipedalism.", "Thinking all hominid fossils come from Europe."],
          [("Why is the Cradle of Humankind a World Heritage Site?", "It has one of the richest collections of hominid fossils in the world."),
           ("Why is mitochondrial DNA useful for tracing ancestry?", "It is passed only from mother to child and changes slowly, so it can be traced back many generations.")],
          lambda X: S(X, [("Evidence for evolution", [(X.pool(HUMAN[21:23] + HUMAN[24:26]), 4), ("caon_hs11:evolution:1", 8), ("in_s12b:evolution:1", 8)]),
                          ("Humans and other primates", [(X.pool(HUMAN[8:15] + HUMAN[23:24] + HUMAN[27:]), 9), ("in_s12b:evolution:5", 7), ("au_sr12b:evolution-and-population-genetics:5", 4)]),
                          ("Fossils in South Africa", [(X.pool(HUMAN[:8] + HUMAN[26:27]), 8), ("cabc_s11:geologic-time-and-dating:4:12", 12)]),
                          ("Out of Africa", [(X.pool(HUMAN[15:21]), 6), ("in_s12b:evolution:5", 4), ("au_sr12b:evolution-and-population-genetics:5", 10)]),
                          ("Human evolution", [("in_s12b:evolution:5", 8), ("au_sr12b:evolution-and-population-genetics:4", 12)])]), g),
    ]
